css_toc:
.toc-wrapper { border-left: 4px solid var(--sd-cyan, #0dcaf0); transition: all 0.3s; }
.toc-link { color: var(--sd-gray, #6c757d); font-weight: 600; text-decoration: none !important; transition: 0.2s; }
.toc-link:hover { color: var(--sl-primary); padding-left: 5px; }

javascript_1_toc_auto:
// 1. TOC AUTOMÁTICO — executa dentro de DOMContentLoaded
if (document.body.classList.contains('is-post')) {
  const article = document.getElementById('article-content');
  if (article) {
    const headings = article.querySelectorAll('h2, h3');
    if (headings.length > 1) {
      const tocWrapper = document.createElement('div');
      tocWrapper.className = 'toc-wrapper bg-body-tertiary p-4 rounded-4 mb-5 shadow-sm';
      tocWrapper.innerHTML = '<h4 class="fw-bold mb-3 fs-5"><i class="bi bi-list-nested me-2"></i> O que você vai ler:</h4><ul class="list-unstyled mb-0" id="toc-list"></ul>';
      const tocList = tocWrapper.querySelector('#toc-list');

      headings.forEach((heading, index) => {
        const id = 'toc-' + index;
        heading.id = id;
        const li = document.createElement('li');
        li.className = 'mb-2';
        if (heading.tagName === 'H3') li.classList.add('ms-4', 'small');
        li.innerHTML = `<a href="#${id}" class="toc-link">${heading.textContent}</a>`;
        tocList.appendChild(li);
      });
      article.insertBefore(tocWrapper, article.firstChild);
    }
  }
}

javascript_2_related_posts:
// 2. POSTS RELACIONADOS — executa dentro de DOMContentLoaded
// Requer: window.postCurrentLabel e window.postCurrentUrl definidos no template
if (document.body.classList.contains('is-post') && window.postCurrentLabel && window.postCurrentUrl) {
  fetch(`/feeds/posts/default/-/${encodeURIComponent(window.postCurrentLabel)}?alt=json&max-results=4`)
    .then(res => res.json())
    .then(data => {
      const container = document.getElementById('related-posts-container');
      if (!container) return;
      const posts = data.feed.entry || [];
      let rendered = 0;
      let html = '';

      posts.forEach(p => {
        const linkObj = p.link.find(l => l.rel === 'alternate');
        if (!linkObj || linkObj.href === window.postCurrentUrl || rendered >= 3) return;
        const title = p.title.$t;
        let img = 'https://via.placeholder.com/600x400?text=Post';
        if (p.media$thumbnail) img = p.media$thumbnail.url.replace(/\/s72-c/, '/w600-h400-c');
        html += `<div class="col-md-4">
  <a href="${linkObj.href}" class="text-decoration-none">
    <div class="card h-100 border-0 shadow-sm rounded-4 overflow-hidden bg-body-tertiary">
      <img src="${img}" class="w-100" style="height:150px;object-fit:cover" alt="${title}">
      <div class="card-body p-3">
        <h4 class="h6 fw-bold text-body mb-0 lh-base">${title}</h4>
      </div>
    </div>
  </a>
</div>`;
        rendered++;
      });

      if (html) container.innerHTML = html;
      else if (container.parentElement) container.parentElement.style.display = 'none';
    })
    .catch(e => console.warn('Related posts error:', e));
}

javascript_3_lazy_loading:
// 3. LAZY LOADING INJECTION — executa dentro de DOMContentLoaded
document.querySelectorAll('.post-body-content img, .post-body-content iframe')
  .forEach(media => {
    if (!media.hasAttribute('loading')) media.setAttribute('loading', 'lazy');
    media.style.transition = 'opacity 0.5s ease-in';
    media.onload = function() { this.style.opacity = 1; };
  });

javascript_4_search_highlight:
// 4. HIGHLIGHT DE BUSCA — executa dentro de DOMContentLoaded
const params = new URLSearchParams(window.location.search);
const termo = params.get('q');
if (termo) {
  const termoLimpo = termo.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const regex = new RegExp(`(${termoLimpo})`, 'gi');
  document.querySelectorAll('.card-game h2 a, .card-game p.text-muted')
    .forEach(el => {
      el.innerHTML = el.innerHTML.replace(regex,
        '<mark class="bg-warning text-dark rounded-1 px-1">$1</mark>');
    });
}
